 <!DOCTYPE html>
 <html lang="en">
 <head>
   <meta charset="UTF-8" />
   <meta name="viewport" content="width=device-width, initial-scale=1.0" />
   <title>Cat FAQ</title>
   <style>
     :root {
       color-scheme: dark;
       --bg: #0b1020;
       --panel: rgba(17, 24, 39, 0.82);
       --panel-border: rgba(148, 163, 184, 0.18);
       --text: #e5eefb;
       --muted: #9fb1cc;
       --accent: #7dd3fc;
       --accent-strong: #38bdf8;
       --shadow: 0 24px 60px rgba(2, 8, 23, 0.48);
     }

     * {
       box-sizing: border-box;
     }

     body {
       margin: 0;
       min-height: 100vh;
       font-family: Inter, ui-sans-serif, system-ui, -apple-system, BlinkMacSystemFont, "Segoe UI", sans-serif;
       background:
         radial-gradient(circle at top, rgba(56, 189, 248, 0.18), transparent 34%),
         linear-gradient(180deg, #0f172a 0%, var(--bg) 100%);
       color: var(--text);
       display: grid;
       place-items: center;
       padding: 32px 18px;
     }

     .app-shell {
       width: min(880px, 100%);
       background: var(--panel);
       border: 1px solid var(--panel-border);
       border-radius: 28px;
       box-shadow: var(--shadow);
       backdrop-filter: blur(14px);
       overflow: hidden;
     }

     .hero {
       padding: 40px 32px 24px;
       border-bottom: 1px solid rgba(148, 163, 184, 0.12);
     }

     .eyebrow {
       display: inline-flex;
       align-items: center;
       gap: 8px;
       padding: 8px 12px;
       border-radius: 999px;
       background: rgba(56, 189, 248, 0.12);
       color: var(--accent);
       font-size: 0.82rem;
       font-weight: 700;
       letter-spacing: 0.04em;
       text-transform: uppercase;
     }

     h1 {
       margin: 18px 0 12px;
       font-size: clamp(2rem, 4vw, 3.3rem);
       line-height: 1.02;
     }

     .hero p {
       margin: 0;
       max-width: 62ch;
       color: var(--muted);
       font-size: 1.02rem;
       line-height: 1.7;
     }

     .faq-list {
       padding: 20px;
       display: grid;
       gap: 14px;
     }

     .example {
       border: 1px solid rgba(148, 163, 184, 0.14);
       background: linear-gradient(180deg, rgba(15, 23, 42, 0.88), rgba(15, 23, 42, 0.65));
       border-radius: 20px;
       overflow: hidden;
       transition: transform 160ms ease, border-color 160ms ease, background 160ms ease;
     }

     .example:hover {
       transform: translateY(-1px);
       border-color: rgba(125, 211, 252, 0.28);
     }

     .question-button {
       width: 100%;
       border: 0;
       background: transparent;
       color: inherit;
       cursor: pointer;
       padding: 22px 24px;
       display: flex;
       align-items: center;
       justify-content: space-between;
       gap: 18px;
       text-align: left;
       font: inherit;
     }

     .question-text {
       font-size: 1.08rem;
       font-weight: 700;
       line-height: 1.5;
     }

     .chevron {
       flex: 0 0 auto;
       width: 18px;
       height: 18px;
       border-right: 2px solid var(--accent);
       border-bottom: 2px solid var(--accent);
       transform: rotate(45deg);
       transition: transform 180ms ease, border-color 180ms ease;
       margin-right: 4px;
     }

     .question-button[aria-expanded="true"] .chevron {
       transform: rotate(-135deg) translateY(-2px);
       border-color: var(--accent-strong);
     }

     .details {
       display: grid;
       grid-template-rows: 0fr;
       transition: grid-template-rows 220ms ease;
     }

     .details.is-open {
       grid-template-rows: 1fr;
     }

     .details-inner {
       min-height: 0;
       overflow: hidden;
     }

     .details-content {
       padding: 0 24px 24px;
       color: #c8d6ea;
       line-height: 1.7;
     }

     .details-content p {
       margin: 0;
     }

     @media (max-width: 640px) {
       .hero {
         padding: 28px 22px 18px;
       }

       .faq-list {
         padding: 14px;
       }

       .question-button,
       .details-content {
         padding-left: 18px;
         padding-right: 18px;
       }
     }
   </style>
 </head>
 <body>
   <div id="app"></div>

   <script>
     const faqs = [
       {
         question: "Why do cats purr?",
         answer: "Cats often purr when they feel relaxed and content, but they may also purr to comfort themselves when stressed or recovering. It is a versatile sound that can signal both pleasure and self-soothing."
       },
       {
         question: "How much do cats sleep each day?",
         answer: "Most cats sleep between 12 and 16 hours a day. Kittens, senior cats, and very active cats may sleep even more depending on their age, health, and environment."
       },
       {
         question: "Why do cats knead blankets or laps?",
         answer: "Kneading is a behavior cats often carry from kittenhood, when they kneaded their mother during nursing. Adult cats usually do it when they feel safe, cozy, and settled."
       },
       {
         question: "Do indoor cats still need playtime?",
         answer: "Yes. Indoor cats benefit from daily play that lets them chase, pounce, and climb. Regular play keeps them mentally stimulated, supports a healthy weight, and reduces boredom."
       },
       {
         question: "What should cats eat?",
         answer: "Cats are obligate carnivores, so they need a nutritionally complete cat food rich in animal-based protein. Fresh water should always be available, and any major diet change should be introduced gradually."
       }
     ];

     const createElement = (tag, className, content) => {
       const element = document.createElement(tag);
       if (className) {
         element.className = className;
       }
       if (content instanceof Node) {
         element.appendChild(content);
       } else if (typeof content === "string") {
         element.textContent = content;
       }
       return element;
     };

     const FAQItem = ({ question, answer }, index) => {
       const example = createElement("div", "example");
       const button = createElement("button", "question-button");
       const details = createElement("div", "details");
       const detailsInner = createElement("div", "details-inner");
       const detailsContent = createElement("div", "details-content");
       const questionText = createElement("span", "question-text", question);
       const chevron = createElement("span", "chevron");
       const answerText = createElement("p", "", answer);

       button.type = "button";
       button.setAttribute("aria-expanded", "false");
       button.setAttribute("aria-controls", "answer-" + index);

       details.id = "answer-" + index;
       detailsInner.appendChild(detailsContent);
       detailsContent.appendChild(answerText);

       button.append(questionText, chevron);
       details.appendChild(detailsInner);
       example.append(button, details);

       button.addEventListener("click", () => {
         const isOpen = button.getAttribute("aria-expanded") === "true";
         button.setAttribute("aria-expanded", String(!isOpen));
         details.classList.toggle("is-open", !isOpen);
       });

       return example;
     };

     const FAQPage = () => {
       const shell = createElement("main", "app-shell");
       const hero = createElement("section", "hero");
       const eyebrow = createElement("div", "eyebrow", "Cat Care FAQ");
       const title = createElement("h1", "", "Common cat questions, answered.");
       const intro = createElement(
         "p",
         "",
         "Explore quick answers about feline behavior, sleep, play, and nutrition. Every question starts collapsed so you can open only what you want to read."
       );
       const faqList = createElement("section", "faq-list");

')
